"use client";

import { UploadIcon } from "./_icons/uplaod";
import { useRouter } from "next/navigation";

import React from "react";

export default function Home() {
  const router = useRouter();

  const fileInputRef = React.useRef<HTMLInputElement>(null);

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (files && files.length > 0) {
      console.log("Selected files:", files);
    }
  };

  const handleUploadClick = () => {
    fileInputRef.current?.click();
  };

  const handleClick = () => {
    router.push("/label");
  };

  return (
    <div className="flex flex-col items-center justify-center min-h-screen py-2">
      <div
        className="border border-gray-300 rounded-md p-4 w-200 h-100
        flex items-center justify-center">
        <input
          type="file"
          ref={fileInputRef}
          onChange={handleFileChange}
          accept="image/*"
          className="hidden"
        />
        <button onClick={handleUploadClick}>
          <UploadIcon />
        </button>
      </div>
      <button
        className="mt-4 bg-blue-500 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded"
        onClick={handleClick}>
        Next: Label photos
      </button>

      <div className="flex flex-col items-center justify-center h-screen gap-10">
        <h1 className="text-2xl font-bold">
          Step 2: Tell the model what each photo is
        </h1>
        <div className="flex gap-10 ">
          <button className="bg-blue-200 text-white px-4 py-2 rounded">
            Cat
          </button>
          <button className="bg-red-200 text-white px-4 py-2 rounded">
            Not a Cat
          </button>
          <button className="bg-yellow-200 text-white px-4 py-2 rounded">
            Still to label
          </button>
        </div>
        <div className="flex gap-50">
          <button className="bg-gray-500 text-white px-4 py-2 rounded">
            Back
          </button>
          <button className="bg-green-500 text-white px-4 py-2 rounded">
            continue
          </button>
        </div>
      </div>
    </div>
  );
}
